<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/admin_guard.php';
$studentId = max(0, (int)($_GET['id'] ?? 0));
if ($studentId < 1) admin_json(422, ['success'=>false,'message'=>'رقم الطالب غير صالح.']);
function nbc_optional_rows(PDO $pdo, string $sql, array $params): array { try { $s=$pdo->prepare($sql); $s->execute($params); return $s->fetchAll(PDO::FETCH_ASSOC) ?: []; } catch (Throwable $e) { error_log('[NBC student details optional query] '.$e->getMessage()); return []; } }
function nbc_optional_one(PDO $pdo, string $sql, array $params): ?array { try { $s=$pdo->prepare($sql); $s->execute($params); $r=$s->fetch(PDO::FETCH_ASSOC); return $r ?: null; } catch (Throwable $e) { error_log('[NBC student details query] '.$e->getMessage()); return null; } }
try {
    $student = nbc_optional_one($pdo, "SELECT id,full_name,email,phone,status,created_at,last_login_at,avatar,bio FROM users WHERE id=? AND role='student' LIMIT 1", [$studentId]);
    if (!$student) admin_json(404, ['success'=>false,'message'=>'الطالب غير موجود أو ليس حساب طالب.']);
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET' && ($_GET['export'] ?? '') === 'csv') {
        $enroll = nbc_optional_rows($pdo, "SELECT c.title AS course_title,e.status,e.access_status,e.enrolled_at,e.completed_at,COUNT(DISTINCT cl.lesson_id) AS total_lessons,COUNT(DISTINCT CASE WHEN lp.status='completed' THEN lp.lesson_id END) AS completed_lessons FROM enrollments e LEFT JOIN courses c ON c.id=e.course_id LEFT JOIN course_lessons cl ON cl.course_id=e.course_id LEFT JOIN lesson_progress lp ON lp.enrollment_id=e.id WHERE e.student_id=? GROUP BY e.id,c.title,e.status,e.access_status,e.enrolled_at,e.completed_at", [$studentId]);
        $payments = nbc_optional_rows($pdo, "SELECT c.title AS course_title,p.amount,p.currency,p.payment_method,p.status,p.transaction_reference,p.paid_at,p.created_at FROM payments p LEFT JOIN courses c ON c.id=p.course_id WHERE p.student_id=? ORDER BY p.created_at DESC", [$studentId]);
        header('Content-Type: text/csv; charset=UTF-8'); header('Content-Disposition: attachment; filename="student-'.$studentId.'-details.csv"'); echo "\xEF\xBB\xBF"; $out=fopen('php://output','w'); fputcsv($out,['نوع البيانات','الاسم','البريد','الهاتف','الحالة','الكورس','القيمة 1','القيمة 2','التاريخ']); fputcsv($out,['student',$student['full_name'],$student['email'],$student['phone'],$student['status'],'','','',$student['created_at']]); foreach($enroll as $e)fputcsv($out,['enrollment',$student['full_name'],$student['email'],$student['phone'],$e['status'],$e['course_title'],$e['completed_lessons'].'/'.$e['total_lessons'],$e['access_status'],$e['enrolled_at']]); foreach($payments as $p)fputcsv($out,['payment',$student['full_name'],$student['email'],$student['phone'],$p['status'],$p['course_title'],$p['amount'].' '.$p['currency'],$p['payment_method'],$p['paid_at']?:$p['created_at']]); fclose($out); exit;
    }
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET') {
        $enrollments = nbc_optional_rows($pdo, "SELECT e.id,e.course_id,e.status,e.access_status,e.enrolled_at,e.completed_at,c.title AS course_title,COUNT(DISTINCT cl.lesson_id) AS total_lessons,COUNT(DISTINCT CASE WHEN lp.status='completed' THEN lp.lesson_id END) AS completed_lessons,CASE WHEN COUNT(DISTINCT cl.lesson_id)>0 THEN ROUND(100*COUNT(DISTINCT CASE WHEN lp.status='completed' THEN lp.lesson_id END)/COUNT(DISTINCT cl.lesson_id),1) ELSE 0 END AS progress_percent FROM enrollments e LEFT JOIN courses c ON c.id=e.course_id LEFT JOIN course_lessons cl ON cl.course_id=e.course_id LEFT JOIN lesson_progress lp ON lp.enrollment_id=e.id AND lp.lesson_id=cl.lesson_id WHERE e.student_id=? GROUP BY e.id,e.course_id,e.status,e.access_status,e.enrolled_at,e.completed_at,c.title ORDER BY e.enrolled_at DESC", [$studentId]);
        $quizzes = nbc_optional_rows($pdo, "SELECT qa.id,qa.quiz_id,q.title AS quiz_title,qa.attempt_number,qa.score,qa.max_score,qa.percent_score,qa.passed,qa.status,qa.started_at,qa.submitted_at FROM quiz_attempts qa LEFT JOIN quizzes q ON q.id=qa.quiz_id WHERE qa.student_id=? ORDER BY COALESCE(qa.submitted_at,qa.started_at) DESC", [$studentId]);
        $assignments = nbc_optional_rows($pdo, "SELECT s.id,s.assignment_id,a.title AS assignment_title,s.submitted_at,s.grade,s.feedback,s.status FROM assignment_submissions s LEFT JOIN assignments a ON a.id=s.assignment_id WHERE s.student_id=? ORDER BY s.submitted_at DESC", [$studentId]);
        $payments = nbc_optional_rows($pdo, "SELECT p.id,p.course_id,c.title AS course_title,p.amount,p.currency,p.payment_method,p.status,p.transaction_reference,p.paid_at,p.created_at FROM payments p LEFT JOIN courses c ON c.id=p.course_id WHERE p.student_id=? ORDER BY p.created_at DESC", [$studentId]);
        $attendance = nbc_optional_rows($pdo, "SELECT ar.id,ar.status,ar.joined_at,ar.left_at,ls.title AS session_title FROM attendance_records ar LEFT JOIN live_sessions ls ON ls.id=ar.live_session_id WHERE ar.student_id=? ORDER BY ar.joined_at DESC", [$studentId]);
        $certificates = nbc_optional_rows($pdo, "SELECT cert.id,cert.course_id,cert.student_name_snapshot,cert.course_title_snapshot,cert.issued_at,cert.revoked_at,c.title AS course_title FROM certificates cert LEFT JOIN courses c ON c.id=cert.course_id WHERE cert.student_id=? ORDER BY cert.issued_at DESC", [$studentId]);
        admin_json(200,['success'=>true,'csrf_token'=>$_SESSION['csrf_token'] ?? '', 'student'=>$student,'enrollments'=>$enrollments,'quiz_attempts'=>$quizzes,'assignments'=>$assignments,'payments'=>$payments,'attendance'=>$attendance,'certificates'=>$certificates]);
    }
    if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') { header('Allow: GET, POST'); admin_json(405,['success'=>false,'message'=>'الطريقة غير مسموح بها.']); }
    $input=json_decode(file_get_contents('php://input'),true); $input=is_array($input)?$input:[]; $action=(string)($input['action']??'');
    if ($action==='status') { $status=(string)($input['status']??''); if(!in_array($status,['active','inactive','suspended'],true))admin_json(422,['success'=>false,'message'=>'حالة الحساب غير صالحة.']); $s=$pdo->prepare("UPDATE users SET status=? WHERE id=? AND role='student'");$s->execute([$status,$studentId]);$log=$pdo->prepare("INSERT INTO audit_logs (actor_user_id,action,entity_type,entity_id,details_json) VALUES (?,?,?,?,?)");$log->execute([(int)$_SESSION['user_id'],'student.status_changed','user',(string)$studentId,json_encode(['status'=>$status],JSON_UNESCAPED_UNICODE)]);admin_json(200,['success'=>true,'message'=>'تم تحديث الحالة.']); }
    if ($action==='update') { $name=trim((string)($input['full_name']??''));$email=trim((string)($input['email']??''));$phone=trim((string)($input['phone']??''));$status=(string)($input['status']??'active');if($name===''||mb_strlen($name)>150||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190||strlen($phone)>30||!in_array($status,['active','inactive','suspended'],true))admin_json(422,['success'=>false,'message'=>'راجع الاسم والبريد والهاتف والحالة.']);$s=$pdo->prepare("UPDATE users SET full_name=?,email=?,phone=?,status=? WHERE id=? AND role='student'");$s->execute([$name,$email,$phone?:null,$status,$studentId]);try{$p=$pdo->prepare("UPDATE profiles SET display_name=? WHERE user_id=?");$p->execute([$name,$studentId]);}catch(Throwable $e){}$log=$pdo->prepare("INSERT INTO audit_logs (actor_user_id,action,entity_type,entity_id,details_json) VALUES (?,?,?,?,?)");$log->execute([(int)$_SESSION['user_id'],'student.updated','user',(string)$studentId,json_encode(['email'=>$email,'status'=>$status],JSON_UNESCAPED_UNICODE)]);admin_json(200,['success'=>true,'message'=>'تم حفظ التعديلات.']); }
    admin_json(422,['success'=>false,'message'=>'الإجراء غير معروف.']);
} catch (PDOException $e) { error_log('[NBC student details] '.$e->getMessage()); if((string)$e->getCode()==='23000')admin_json(409,['success'=>false,'message'=>'البريد الإلكتروني مستخدم بالفعل.']); admin_json(500,['success'=>false,'message'=>'تعذر تحميل أو حفظ بيانات الطالب.']); } catch(Throwable $e){error_log('[NBC student details] '.$e->getMessage());admin_json(500,['success'=>false,'message'=>'حدث خطأ غير متوقع.']);}
